            int64_t d_model,
            int64_t n_head,
            int64_t intermediate_size,
            bool proj_in = false)
    : n_layer(n_layer) {
    for (int i = 0; i < n_layer; i++) {
        std::string name = "layers." + std::to_string(i);
        blocks[name]     = std::shared_ptr<GGMLBlock>(new CLIPLayer(d_model, n_head, intermediate_size, proj_in));
    }
}

