__STATIC_INLINE__ std::vector<float> flatten(const std::vector<std::vector<float>>& vec) {
    std::vector<float> flat_vec;
    for (const auto& sub_vec : vec) {
        flat_vec.insert(flat_vec.end(), sub_vec.begin(), sub_vec.end());
    }
    return flat_vec;
}

