        blocks["net.0"] = std::shared_ptr<GGMLBlock>(new GELU(dim, inner_dim));
    } else {
        blocks["net.0"] = std::shared_ptr<GGMLBlock>(new GEGLU(dim, inner_dim));
    }

    // net_1 is nn.Dropout(), skip for inference
