        const int s1 = wrap_add(i1, shNe1, ne1);
        const int s2 = wrap_add(i2, shNe2, ne2);
        const int s3 = wrap_add(i3, shNe3, ne3);

        const int idx_src = s0
                          + s1 * stride1
                          + s2 * stride2
                          + s3 * stride3;

        dst_d[idx_dst] = src_d[idx_src];
    });
});

